        foreach ($quranVerses as $v) {
            $this->db->table('quran_verses')->insert(['surah' => $v['surah'], 'ayat_number' => $v['ayat_number'], 'arabic_text' => $v['arabic_text'], 'translation' => $v['translation'], 'source' => "Al-Qur'an", 'tags' => $v['tags'], 'status' => 'approved', 'created_at' => $now, 'updated_at' => $now]);
